#!/usr/bin/env python3
"""Generate the KXemu virt device tree for KernelX with SMP harts."""

import argparse


HEADER = """/dts-v1/;

/*
 * Generated by gen-dts.py for SMP={smp}.
 *
 * KXemu memory layout (see kernelx-riscv64.kdb):
 *   0x80000000  OpenSBI fw_jump.bin
 *   0x80200000  KernelX Image
 *   0x82200000  this device tree (OpenSBI fw_jump's fixed FDT address)
 *
 * KernelX takes its boot parameters from /chosen/bootargs. The root
 * filesystem is the virtio-mmio block device at 0x10001000 (PLIC IRQ 1).
 */

/ {{
\t#address-cells = <0x02>;
\t#size-cells = <0x02>;
\tcompatible = "riscv-virtio";
\tmodel = "riscv-virtio,kxemu";

\tmemory@80000000 {{
\t\tdevice_type = "memory";
\t\treg = <0x00 0x80000000 0x00 0x10000000>;
\t}};

\tcpus {{
\t\t#address-cells = <0x01>;
\t\t#size-cells = <0x00>;
\t\ttimebase-frequency = <0x989680>;
"""

CPU = """
\t\tcpu{hart}: cpu@{hart} {{
\t\t\tdevice_type = "cpu";
\t\t\treg = <0x{hart:02x}>;
\t\t\tstatus = "okay";
\t\t\tcompatible = "riscv";
\t\t\triscv,isa = "rv64imafdc_zicsr_zifencei";
\t\t\tmmu-type = "riscv,sv39";

\t\t\tcpu{hart}_intc: interrupt-controller {{
\t\t\t\t#address-cells = <0x00>;
\t\t\t\t#interrupt-cells = <0x01>;
\t\t\t\tinterrupt-controller;
\t\t\t\tcompatible = "riscv,cpu-intc";
\t\t\t}};
\t\t}};
"""

CPU_MAP_INTRO = """
\t\tcpu-map {
\t\t\tcluster0 {
"""

CPU_MAP_ENTRY = """\t\t\t\tcore{hart} {{
\t\t\t\t\tcpu = <&cpu{hart}>;
\t\t\t\t}};
"""

CPU_MAP_OUTRO = """\t\t\t};
\t\t};
\t};
"""

SOC = """
\tchosen {{
\t\tbootargs = "root=virtio_mmio@10001000 rootfstype=ext4 init=/init initcwd=/ initargs=\\"/dev/serial@10000000 /hello\\"";
\t}};

\tsoc {{
\t\t#address-cells = <0x02>;
\t\t#size-cells = <0x02>;
\t\tcompatible = "simple-bus";
\t\tranges;

\t\tserial@10000000 {{
\t\t\tinterrupts = <0x0a>;
\t\t\tinterrupt-parent = <&plic>;
\t\t\tclock-frequency = <0x989680>;
\t\t\treg = <0x00 0x10000000 0x00 0x100>;
\t\t\tcompatible = "ns16550a";
\t\t}};

\t\tplic: plic@c000000 {{
\t\t\triscv,ndev = <0x5f>;
\t\t\treg = <0x00 0xc000000 0x00 0x4000000>;
\t\t\tinterrupts-extended = <{plic_pairs}>;
\t\t\tinterrupt-controller;
\t\t\tcompatible = "sifive,plic-1.0.0\\0riscv,plic0";
\t\t\t#address-cells = <0x00>;
\t\t\t#interrupt-cells = <0x01>;
\t\t}};

\t\tclint@2000000 {{
\t\t\tinterrupts-extended = <{clint_pairs}>;
\t\t\treg = <0x00 0x2000000 0x00 0x10000>;
\t\t\tcompatible = "sifive,clint0\\0riscv,clint0";
\t\t}};

\t\tvirtio_mmio@10001000 {{
\t\t\tinterrupts = <0x01>;
\t\t\tinterrupt-parent = <&plic>;
\t\t\treg = <0x00 0x10001000 0x00 0x1000>;
\t\t\tcompatible = "virtio,mmio";
\t\t}};
\t}};
}};
"""


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--smp", type=int, default=4, help="number of harts")
    parser.add_argument("--output", required=True, help="output .dts path")
    args = parser.parse_args()

    if not 1 <= args.smp <= 32:
        parser.error("--smp must be between 1 and 32")

    text = HEADER.format(smp=args.smp)
    for hart in range(args.smp):
        text += CPU.format(hart=hart)

    text += CPU_MAP_INTRO
    for hart in range(args.smp):
        text += CPU_MAP_ENTRY.format(hart=hart)
    text += CPU_MAP_OUTRO

    # PLIC contexts are ordered M,S per hart: hart i owns contexts 2i and 2i+1.
    plic_pairs = " ".join(
        f"&cpu{hart}_intc 0x0b &cpu{hart}_intc 0x09" for hart in range(args.smp)
    )
    clint_pairs = " ".join(
        f"&cpu{hart}_intc 0x03 &cpu{hart}_intc 0x07" for hart in range(args.smp)
    )
    text += SOC.format(plic_pairs=plic_pairs, clint_pairs=clint_pairs)

    with open(args.output, "w", encoding="ascii") as f:
        f.write(text)


if __name__ == "__main__":
    main()
